{
  "name": "BuildScan AI",
  "description": "A professional construction order analyzer that extracts structured data from scans and PDFs using Gemini AI, ensuring confidentiality and accuracy for operational workflows."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ConstructionOrderData {
  num_bon_travaux: string | null;
  adresse_intervention: string | null;
  coord_gardien: string | null;
  nom_client: string | null;
  delai_intervention: string | null;
  date_intervention: string | null;
}

export interface ExtractionResult {
  data: ConstructionOrderData;
  rawJson: string;
}

export enum AppStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  ANALYZING = 'ANALYZING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionOrderData } from "../types";

const SYSTEM_INSTRUCTION = `Tu es un agent spécialisé dans l'analyse de documents de construction. Ton rôle est d'extraire des données structurées depuis des scans de bons de commande.

Instructions d'extraction :
- num_bon_travaux : Extraire le numéro de référence du bon.
- adresse_intervention : Adresse complète du chantier.
- coord_gardien : Nom/Téléphone du contact sur place.
- nom_client : Nom de l'entreprise ou du donneur d'ordre.
- delai_intervention : Période ou durée de validité.
- date_intervention : Date spécifique de rendez-vous si mentionnée.

Règles critiques :
1. CONFIDENTIALITÉ : Ne jamais extraire de prix, de montants HT, TTC ou de taux de TVA. Ignore totalement ces zones.
2. FORMAT : Réponds exclusivement au format JSON.
3. NULLITÉ : Si un champ n'est pas trouvé, inscris null.
4. LANGUE : Conserve le texte original pour les adresses et noms.`;

const RESPONSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    num_bon_travaux: { type: Type.STRING, description: "Référence du bon" },
    adresse_intervention: { type: Type.STRING, description: "Adresse du chantier" },
    coord_gardien: { type: Type.STRING, description: "Contact gardien/client" },
    nom_client: { type: Type.STRING, description: "Nom du donneur d'ordre" },
    delai_intervention: { type: Type.STRING, description: "Délai de validité" },
    date_intervention: { type: Type.STRING, description: "Date prévue" },
  },
  required: ["num_bon_travaux", "adresse_intervention", "coord_gardien", "nom_client", "delai_intervention", "date_intervention"]
};

export async function analyzeConstructionDocument(base64Data: string, mimeType: string): Promise<ConstructionOrderData> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType
          }
        },
        {
          text: "Analyse cet image de bon de commande et extrait les informations selon le schéma défini."
        }
      ]
    },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: RESPONSE_SCHEMA
    }
  });

  const text = response.text;
  if (!text) throw new Error("Aucune donnée extraite");

  try {
    return JSON.parse(text) as ConstructionOrderData;
  } catch (err) {
    console.error("Failed to parse JSON response:", text);
    throw new Error("Erreur de parsing des données extraites.");
  }
}

import React, { useState, useCallback } from 'react';
import { AppStatus, ConstructionOrderData } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);

  const handleFileSelect = useCallback(async (file: File) => {
    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);

    try {
      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setFilePreview(reader.result as string);
      };
      reader.readAsDataURL(file);

      // Extract base64 for API
      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
          const base64 = (reader.result as string).split(',')[1];
          resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Une erreur est survenue lors de l'analyse.");
      setStatus(AppStatus.ERROR);
    }
  }, []);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setFilePreview(null);
    setExtractedData(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8">
        <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Upload & Preview */}
          <div className="lg:col-span-5 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                <i className="fas fa-file-upload text-blue-600"></i>
                Document Source
              </h2>

              <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />

              {filePreview && (
                <div className="mt-6">
                  <p className="text-sm font-medium text-slate-500 mb-2 uppercase tracking-wider">Aperçu du document</p>
                  <div className="relative border border-slate-200 rounded-lg overflow-hidden bg-slate-100 min-h-[300px] flex items-center justify-center">
                    <img 
                      src={filePreview} 
                      alt="Aperçu" 
                      className="max-w-full h-auto shadow-lg"
                    />
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right Column: Analysis & Results */}
          <div className="lg:col-span-7 space-y-6">
            {status === AppStatus.IDLE && !error && (
              <div className="bg-blue-50 border border-blue-100 rounded-xl p-8 text-center">
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <i className="fas fa-robot text-2xl"></i>
                </div>
                <h3 className="text-lg font-semibold text-blue-900 mb-2">Prêt pour l'analyse</h3>
                <p className="text-blue-700">Téléchargez un bon de commande (Image ou Scan) pour extraire automatiquement les données chantiers.</p>
              </div>
            )}

            {status === AppStatus.ANALYZING && (
              <div className="bg-white border border-slate-200 rounded-xl p-12 text-center shadow-sm">
                <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-600 border-t-transparent mb-4"></div>
                <h3 className="text-xl font-bold text-slate-800">Analyse intelligente en cours...</h3>
                <p className="text-slate-500 mt-2 italic">Gemini examine la mise en page et extrait les coordonnées...</p>
              </div>
            )}

            {status === AppStatus.ERROR && (
              <div className="bg-red-50 border border-red-200 rounded-xl p-6 text-center">
                <i className="fas fa-exclamation-triangle text-red-500 text-3xl mb-3"></i>
                <h3 className="text-lg font-bold text-red-800">Échec de l'analyse</h3>
                <p className="text-red-700 mb-4">{error}</p>
                <button 
                  onClick={reset}
                  className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                >
                  Réessayer
                </button>
              </div>
            )}

            {extractedData && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6">
                <ResultCard data={extractedData} onReset={reset} />
                <SqlExporter data={extractedData} />
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center text-slate-500 text-sm">
          BuildScan AI &copy; {new Date().getFullYear()} - Outil interne d'extraction de données BTP.
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';

interface FileUploaderProps {
  onFileSelect: (file: File) => void;
  disabled?: boolean;
}

const FileUploader: React.FC<FileUploaderProps> = ({ onFileSelect, disabled }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onFileSelect(file);
    }
  };

  return (
    <div className={`relative group ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}>
      <input
        type="file"
        accept="image/*"
        onChange={handleChange}
        disabled={disabled}
        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed z-10"
      />
      <div className="border-2 border-dashed border-slate-300 group-hover:border-blue-500 group-hover:bg-blue-50 transition-all rounded-xl p-10 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 mb-4 bg-slate-100 group-hover:bg-blue-100 text-slate-400 group-hover:text-blue-600 rounded-full flex items-center justify-center transition-colors">
          <i className="fas fa-cloud-arrow-up text-3xl"></i>
        </div>
        <p className="text-slate-700 font-bold mb-1">Cliquer pour télécharger</p>
        <p className="text-slate-400 text-xs uppercase tracking-widest font-semibold">JPG, PNG ou PDF (Image)</p>
      </div>
    </div>
  );
};

export default FileUploader;

