export default ResultCard;

import React, { useState } from 'react';
import { ConstructionOrderData } from '../types';

interface SqlExporterProps {
  data: ConstructionOrderData;
}

const SqlExporter: React.FC<SqlExporterProps> = ({ data }) => {
  const [copied, setCopied] = useState(false);

  const escapeSql = (str: string | null) => str ? str.replace(/'/g, "''") : "NULL";

  const sqlSchema = `CREATE TABLE IF NOT EXISTS bons_commande (
  id INT AUTO_INCREMENT PRIMARY KEY,
  num_bon_travaux VARCHAR(255),
  adresse_intervention TEXT,
  coord_gardien VARCHAR(255),
  nom_client VARCHAR(255),
  delai_intervention VARCHAR(255),
  date_intervention VARCHAR(255),
  date_import DATETIME DEFAULT CURRENT_TIMESTAMP
);`;

  const sqlInsert = `INSERT INTO bons_commande 
(num_bon_travaux, adresse_intervention, coord_gardien, nom_client, delai_intervention, date_intervention) 
VALUES 
('${escapeSql(data.num_bon_travaux)}', '${escapeSql(data.adresse_intervention)}', '${escapeSql(data.coord_gardien)}', '${escapeSql(data.nom_client)}', '${escapeSql(data.delai_intervention)}', '${escapeSql(data.date_intervention)}');`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(sqlInsert);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800">
      <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <i className="fas fa-database text-blue-400"></i>
          <h3 className="text-white font-bold">Intégration MySQL</h3>
        </div>
        <button 
          onClick={copyToClipboard}
          className={`text-xs font-bold px-3 py-1.5 rounded transition-all flex items-center gap-2 ${copied ? 'bg-green-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
        >
          {copied ? <><i className="fas fa-check"></i> Copié !</> : <><i className="fas fa-copy"></i> Copier l'INSERT</>}
        </button>
      </div>

      <div className="p-6">
        <div className="mb-6">
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Schéma de la table</p>
          <pre className="bg-black/50 p-4 rounded-lg text-blue-300 text-xs font-mono overflow-x-auto border border-slate-800">
            {sqlSchema}
          </pre>
        </div>

        <div>
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Requête d'insertion</p>
          <pre className="bg-black/50 p-4 rounded-lg text-emerald-300 text-xs font-mono overflow-x-auto border border-slate-800">
            {sqlInsert}
          </pre>
        </div>
      </div>

      <div className="bg-slate-800/50 px-6 py-3 flex items-center gap-4">
        <div className="flex -space-x-2">
          <div className="w-8 h-8 rounded-full bg-slate-700 border-2 border-slate-900 flex items-center justify-center text-[10px] text-white font-bold" title="Kizeo Ready">K</div>
          <div className="w-8 h-8 rounded-full bg-blue-600 border-2 border-slate-900 flex items-center justify-center text-[10px] text-white font-bold" title="MySQL Ready">M</div>
          <div className="w-8 h-8 rounded-full bg-slate-600 border-2 border-slate-900 flex items-center justify-center text-[10px] text-white font-bold" title="Nextcloud Ready">N</div>
        </div>
        <p className="text-[10px] text-slate-400 font-medium">Compatible avec Kizeo Forms, MySQL et stockage Nextcloud.</p>
      </div>
    </div>
  );
};

export default SqlExporter;

