import React, { useState, useMemo } from 'react';
import { ConstructionOrderData, Client } from '../types';

interface SqlExporterProps {
  data: ConstructionOrderData;
}

const SqlExporter: React.FC<SqlExporterProps> = ({ data }) => {
  const [copied, setCopied] = useState(false);

  // Recherche du mapping client
  const mappedClient = useMemo(() => {
    if (!data.nom_client) return null;
    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return null;
    try {
      const clients: Client[] = JSON.parse(saved);
      return clients.find(c => 
        c.nom.toLowerCase() === data.nom_client?.toLowerCase() ||
        data.nom_client?.toLowerCase().includes(c.nom.toLowerCase())
      );
    } catch (e) {
      return null;
    }
  }, [data.nom_client]);

  const escapeSql = (str: string | null) => str ? str.replace(/'/g, "''").trim() : "";

  const soc = "SAM";
  const ets = "001";
  const secteur = "80";
  const phase = "0";

  const chantier = escapeSql(data.num_bon_travaux).replace(/\D/g, '').substring(0, 6) || "000000";
  const imputation = `${secteur}${chantier}${phase}`;

  const fullAddress = escapeSql(data.adresse_intervention);
  const cpMatch = fullAddress.match(/\d{5}/);
  const codePostal = cpMatch ? cpMatch[0] : "";

  // Utilisation des données mappées ou valeurs par défaut
  const codeCliFour = mappedClient ? mappedClient.codeClient : "";
  const codeTrv = mappedClient ? mappedClient.typeAffaire : "O3-0";

  const sqlInsert = `INSERT INTO \`a_cht\` 
(\`soc\`, \`ets\`, \`secteur\`, \`chantier\`, \`phase\`, \`imputation\`, \`libelle1\`, \`descriptif_tvx\`, \`descriptif_trvx2\`, \`code_postal\`, \`inter_cli\`, \`tel_cli\`, \`code_ouvert\`, \`code_raz_fin_exo\`, \`code_clifour\`, \`code_trv\`) 
VALUES 
(
  '${soc}', 
  '${ets}', 
  '${secteur}', 
  '${chantier}', 
  '${phase}', 
  '${imputation}', 
  '${escapeSql(data.nom_client).substring(0, 40)}', 
  '<p>Import BuildScan AI : ${escapeSql(data.coord_gardien)}</p>', 
  '${fullAddress.substring(0, 120)}', 
  '${codePostal}', 
  '${escapeSql(data.nom_client).substring(0, 40)}', 
  '${escapeSql(data.coord_gardien).substring(0, 30)}', 
  '4', 
  'N',
  '${codeCliFour}',
  '${codeTrv}'
);`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(sqlInsert);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800">
      <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <i className="fas fa-database text-blue-400"></i>
          <h3 className="text-white font-bold uppercase tracking-wider text-sm">Export ERP <span className="text-blue-400">SAMDB</span></h3>
        </div>
        <div className="flex gap-2">
           <button 
            onClick={copyToClipboard}
            className={`text-xs font-bold px-3 py-1.5 rounded transition-all flex items-center gap-2 ${copied ? 'bg-green-600 text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          >
            {copied ? <><i className="fas fa-check"></i> Copié !</> : <><i className="fas fa-copy"></i> Copier l'INSERT a_cht</>}
          </button>
        </div>
      </div>

      <div className="p-6">
        <div className="mb-4 flex items-center gap-3 bg-slate-800/50 p-3 rounded-lg border border-slate-700">
            <div className="w-10 h-10 bg-slate-700 rounded flex items-center justify-center text-blue-400">
                <i className="fas fa-microchip"></i>
            </div>
            <div>
                <p className="text-xs text-slate-300 font-bold uppercase">Table Cible : a_cht</p>
                <p className="text-[10px] text-slate-500">Mapping automatique vers samdb {mappedClient ? '(Client mappé détecté)' : '(Sans mapping client)'}</p>
            </div>
        </div>

        <div>
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Requête SQL générée</p>
          <pre className="bg-black/50 p-4 rounded-lg text-emerald-300 text-[11px] font-mono overflow-x-auto border border-slate-800 leading-relaxed">
            {sqlInsert}
          </pre>
        </div>
      </div>

      <div className="bg-slate-800/50 px-6 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full animate-pulse ${mappedClient ? 'bg-green-500' : 'bg-amber-500'}`}></span>
            <p className="text-[10px] text-slate-400 font-medium italic">
                {mappedClient ? `Client ${mappedClient.codeClient} injecté.` : 'Attention: Code client manquant dans SQL.'}
            </p>
        </div>
        <div className="text-[10px] text-slate-500 font-mono">SAMDB Compatibility Mode</div>
      </div>
    </div>
  );
};

