}

export async function fetchStorageConfig(): Promise<StorageConfig | null> {
  try {
    // On force le rafraîchissement avec un paramètre de temps pour éviter le cache navigateur
    const response = await fetch(`/storage.json?t=${Date.now()}`);
    if (!response.ok) throw new Error('Fichier storage.json introuvable');
    return await response.json();
  } catch (err) {
    console.error('Erreur lecture storage.json:', err);
    return null;
  }
