export async function analyzeConstructionDocument(base64Data: string, mimeType: string): Promise<ConstructionOrderData> {
  // Initialisation à chaque appel pour garantir la récupération de la clé API la plus fraîche
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType
          }
        },
        {
          text: "Analyse ce document et extrais les données au format JSON."
        }
      ]
    },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: RESPONSE_SCHEMA
    }
  });

  const text = response.text;
  if (!text) {
    throw new Error("Le modèle n'a renvoyé aucune réponse.");
  }

  // Nettoyage au cas où le modèle renvoie des balises Markdown ```json ... ```
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  const cleanJson = jsonMatch ? jsonMatch[0] : text;

  try {
    return JSON.parse(cleanJson) as ConstructionOrderData;
  } catch (err) {
    console.error("Erreur de parsing JSON. Texte brut:", text);
    throw new Error("Format de réponse invalide. Impossible de parser les données.");
  }
