import SqlExporter from './components/SqlExporter';
import AdminPoseurs from './components/AdminPoseurs';
import AdminClients from './components/AdminClients';
import AdminWebhook from './components/AdminWebhook';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingView, setPendingView] = useState<AppView | null>(null);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      await fetchStorageConfig(); // Pré-chargement du cache
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  const handleViewChange = (view: AppView) => {
    if (view === 'analyzer') {
      setCurrentView('analyzer');
      return;
    }

    // Protection des vues admin
    if (isAuthenticated) {
      setCurrentView(view);
    } else {
      setPendingView(view);
      setShowAuthModal(true);
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    if (pendingView) {
      setCurrentView(pendingView);
      setPendingView(null);
    }
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    setPendingView(null);
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setOriginalFile(file);

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) {
        msg = "Quota dépassé (Erreur 429). Veuillez patienter 60 secondes.";
      }
      setError(msg);
      setStatus(AppStatus.ERROR);
    }
  }, []);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setError(null);
    setOriginalFile(null);
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <Header currentView={currentView} onViewChange={handleViewChange} />

      {showAuthModal && (
        <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />
      )}

      <main className="flex-grow container mx-auto px-4 py-8">
        <div className="max-w-6xl mx-auto">
          {currentView === 'admin_poseurs' && <AdminPoseurs />}
          {currentView === 'admin_clients' && <AdminClients />}
          {currentView === 'admin_webhook' && <AdminWebhook />}

          {currentView === 'analyzer' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-5 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <h2 className="text-xl font-black mb-4 flex items-center gap-2 uppercase tracking-tight">
                    <i className="fas fa-file-pdf text-blue-600"></i>
                    Document Source
                  </h2>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />

                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300">
                      <p className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest text-center">Aperçu du scan</p>
                      <div className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner">
                        <iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none" />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div className="lg:col-span-7 space-y-6">
                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm">
                      <i className="fas fa-robot text-4xl"></i>
                    </div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
                        <i className="fas fa-exclamation-triangle text-xl"></i>
                      </div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">
                          Réessayer
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    <ResultCard data={extractedData} onReset={reset} />
                    <SqlExporter data={extractedData} originalFile={originalFile || undefined} />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center">
          <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.5 • PocketBase Ed.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { fetchStorageConfig, addClient, updateClient, deleteClient } from '../services/configService';

const AdminClients: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newClient, setNewClient] = useState<Omit<Client, 'id'>>({ nom: '', codeClient: '', typeAffaire: '' });
  const [editForm, setEditForm] = useState<Omit<Client, 'id'>>({ nom: '', codeClient: '', typeAffaire: '' });

  const reloadClients = async () => {
    const config = await fetchStorageConfig();
    if (config) setClients(config.clients);
  };

  useEffect(() => { reloadClients(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newClient.nom || !newClient.codeClient) return;
    setIsSaving(true);
    const result = await addClient(newClient);
    if (result) {
      setNewClient({ nom: '', codeClient: '', typeAffaire: '' });
      setIsAdding(false);
      await reloadClients();
    } else {
      alert("Erreur serveur lors de l'ajout.");
    }
    setIsSaving(false);
  };

  const handleUpdate = async (id: string) => {
    setIsSaving(true);
    const success = await updateClient(id, editForm);
    if (success) {
      setEditingId(null);
      await reloadClients();
    } else {
      alert("Erreur serveur lors de la mise à jour.");
    }
    setIsSaving(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Supprimer ce client du référentiel ?")) return;
    setIsSaving(true);
    const success = await deleteClient(id);
    if (success) await reloadClients();
    setIsSaving(false);
  };

  const startEditing = (client: Client) => {
    setEditingId(client.id);
    setEditForm({ nom: client.nom, codeClient: client.codeClient, typeAffaire: client.typeAffaire });
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Référentiel Clients</h2>
          <p className="text-slate-500">Base de données PocketBase.</p>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => { setIsAdding(!isAdding); setEditingId(null); }}
            className={`px-5 py-2.5 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm ${
              isAdding ? 'bg-slate-200 text-slate-700' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-200'
            }`}
          >
            {isAdding ? 'Annuler' : <><i className="fas fa-plus-circle"></i> Ajouter</>}
          </button>
        </div>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white border-2 border-blue-100 rounded-2xl p-6 shadow-xl grid grid-cols-1 md:grid-cols-3 gap-5 animate-in slide-in-from-top-4">
          <input type="text" required placeholder="Nom (PDF)" className="w-full p-2.5 border rounded-xl" value={newClient.nom} onChange={e => setNewClient({...newClient, nom: e.target.value})} />
          <input type="text" required placeholder="Code ERP" className="w-full p-2.5 border rounded-xl font-mono" value={newClient.codeClient} onChange={e => setNewClient({...newClient, codeClient: e.target.value})} />
          <input type="text" placeholder="Type Affaire" className="w-full p-2.5 border rounded-xl font-mono" value={newClient.typeAffaire} onChange={e => setNewClient({...newClient, typeAffaire: e.target.value})} />
          <button type="submit" disabled={isSaving} className="md:col-span-3 bg-emerald-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-emerald-700 shadow-lg transition-all">
            {isSaving ? 'Enregistrement...' : 'Créer dans PocketBase'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Nom PDF</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Code ERP</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Type</th>
              <th className="px-6 py-4 text-right text-[10px] font-black text-slate-400 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {clients.map(c => (
              <tr key={c.id} className="hover:bg-slate-50/80">
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded" value={editForm.nom} onChange={e => setEditForm({...editForm, nom: e.target.value})} /> : <span className="font-bold">{c.nom}</span>}
                </td>
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded font-mono" value={editForm.codeClient} onChange={e => setEditForm({...editForm, codeClient: e.target.value})} /> : <code className="bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold">{c.codeClient}</code>}
                </td>
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded font-mono" value={editForm.typeAffaire} onChange={e => setEditForm({...editForm, typeAffaire: e.target.value})} /> : c.typeAffaire}
                </td>
                <td className="px-6 py-4 text-right flex justify-end gap-2">
                  {editingId === c.id ? (
                    <>
                      <button onClick={() => handleUpdate(c.id)} className="text-emerald-600 hover:text-emerald-800"><i className="fas fa-check"></i></button>
                      <button onClick={() => setEditingId(null)} className="text-slate-400 hover:text-slate-600"><i className="fas fa-times"></i></button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => startEditing(c)} className="text-blue-500 hover:text-blue-700"><i className="fas fa-edit"></i></button>
                      <button onClick={() => handleDelete(c.id)} className="text-red-400 hover:text-red-600"><i className="fas fa-trash"></i></button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminClients;

import React, { useState, useEffect } from 'react';
import { Poseur } from '../types';
import { fetchStorageConfig, addPoseur, updatePoseur, deletePoseur } from '../services/configService';

const AdminPoseurs: React.FC = () => {
  const [poseurs, setPoseurs] = useState<Poseur[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const initialForm = { nom: '', entreprise: '', telephone: '', specialite: '', codeSalarie: '' };
  const [newPoseur, setNewPoseur] = useState<Omit<Poseur, 'id'>>(initialForm);
  const [editForm, setEditForm] = useState<Omit<Poseur, 'id'>>(initialForm);

  const reloadPoseurs = async () => {
    const config = await fetchStorageConfig();
    if (config) setPoseurs(config.poseurs);
  };

  useEffect(() => { reloadPoseurs(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const result = await addPoseur(newPoseur);
    if (result) {
      setNewPoseur(initialForm);
      setIsAdding(false);
      await reloadPoseurs();
    }
    setIsSaving(false);
  };

  const handleUpdate = async (id: string) => {
    setIsSaving(true);
    const success = await updatePoseur(id, editForm);
    if (success) {
      setEditingId(null);
      await reloadPoseurs();
    }
    setIsSaving(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Supprimer ce poseur ?")) return;
    setIsSaving(true);
    const success = await deletePoseur(id);
    if (success) await reloadPoseurs();
    setIsSaving(false);
  };

  const startEditing = (p: Poseur) => {
    setEditingId(p.id);
    setEditForm({ nom: p.nom, entreprise: p.entreprise, telephone: p.telephone, specialite: p.specialite, codeSalarie: p.codeSalarie });
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-slate-800">Gestion Flotte</h2>
        <button onClick={() => setIsAdding(!isAdding)} className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold">
          {isAdding ? 'Annuler' : '+ Poseur'}
        </button>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white p-6 rounded-xl border border-indigo-100 shadow-lg grid grid-cols-1 md:grid-cols-2 gap-4">
          <input placeholder="Nom" className="p-2 border rounded" value={newPoseur.nom} onChange={e => setNewPoseur({...newPoseur, nom: e.target.value})} />
          <input placeholder="Entreprise" className="p-2 border rounded" value={newPoseur.entreprise} onChange={e => setNewPoseur({...newPoseur, entreprise: e.target.value})} />
          <input placeholder="Téléphone" className="p-2 border rounded" value={newPoseur.telephone} onChange={e => setNewPoseur({...newPoseur, telephone: e.target.value})} />
          <input placeholder="Code Salarié" className="p-2 border rounded" value={newPoseur.codeSalarie} onChange={e => setNewPoseur({...newPoseur, codeSalarie: e.target.value})} />
          <button type="submit" disabled={isSaving} className="col-span-2 bg-emerald-600 text-white py-2 rounded font-bold">Ajouter</button>
        </form>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {poseurs.map(p => (
          <div key={p.id} className="p-4 border-b last:border-0 flex items-center justify-between hover:bg-slate-50">
            {editingId === p.id ? (
              <div className="w-full flex gap-2">
                <input className="border p-1 rounded flex-1" value={editForm.nom} onChange={e => setEditForm({...editForm, nom: e.target.value})} />
                <button onClick={() => handleUpdate(p.id)} className="bg-emerald-500 text-white px-3 rounded">OK</button>
                <button onClick={() => setEditingId(null)} className="bg-slate-400 text-white px-3 rounded">X</button>
              </div>
            ) : (
              <>
                <div>
                  <div className="font-bold">{p.nom}</div>
                  <div className="text-xs text-slate-500">{p.entreprise} • {p.telephone}</div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => startEditing(p)} className="text-indigo-600"><i className="fas fa-edit"></i></button>
                  <button onClick={() => handleDelete(p.id)} className="text-red-500"><i className="fas fa-trash"></i></button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdminPoseurs;

import React, { useState, useEffect } from 'react';
import { fetchStorageConfig, updateWebhookUrl } from '../services/configService';

const AdminWebhook: React.FC = () => {
  const [url, setUrl] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');

  useEffect(() => {
    const load = async () => {
      const config = await fetchStorageConfig();
      if (config) setUrl(config.webhook_url);
    };
    load();
  }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setStatus('idle');

    const success = await updateWebhookUrl(url);
    if (success) {
      setStatus('success');
      setTimeout(() => setStatus('idle'), 3000);
    } else {
      setStatus('error');
    }
    setIsSaving(false);
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6 animate-in fade-in duration-500">
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
        <div className="flex items-center gap-4 mb-6">
          <div className="w-12 h-12 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center text-xl">
            <i className="fas fa-network-wired"></i>
          </div>
          <div>
            <h2 className="text-2xl font-bold text-slate-800">Configuration Webhook</h2>
            <p className="text-slate-500 text-sm">Synchronisation Cloud PocketBase</p>
          </div>
        </div>

        <form onSubmit={handleSave} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest">URL n8n / ERP</label>
            <input 
              type="url" 
              required
              className="w-full p-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm bg-slate-50"
              value={url}
              onChange={e => setUrl(e.target.value)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {status === 'success' && <span className="text-emerald-600 text-xs font-bold"><i className="fas fa-check-circle"></i> URL mise à jour</span>}
              {status === 'error' && <span className="text-red-600 text-xs font-bold"><i className="fas fa-times-circle"></i> Échec connexion PocketBase</span>}
            </div>
            <button 
              type="submit" 
              disabled={isSaving}
              className={`px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 ${
                isSaving ? 'bg-slate-400' : 'bg-blue-600 text-white hover:bg-blue-700'
              }`}
            >
              {isSaving ? <i className="fas fa-sync animate-spin"></i> : <i className="fas fa-cloud-upload-alt"></i>}
              Enregistrer
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminWebhook;

