  id: string;
  nom: string; // Nom tel qu'il apparaît sur les PDF
  codeClient: string; // ex: 411DRA038
  typeAffaire: string; // ex: O3-0
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'request' | 'response' | 'error';
  message: string;
  data?: any;
}

export interface ExtractionResult {
  data: ConstructionOrderData;
  rawJson: string;
}

export enum AppStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  ANALYZING = 'ANALYZING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export type AppView = 'analyzer' | 'admin';

import React, { useState } from 'react';
import AdminClients from './AdminClients';
import AdminPoseurs from './AdminPoseurs';
import AdminWebhook from './AdminWebhook';

type AdminTab = 'clients' | 'poseurs' | 'config';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>('clients');

  const menuItems = [
