                  ? 'bg-slate-100 text-slate-400 border-slate-200' 
                  : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300'
              }`}
            >
              {isTesting ? (
                <><i className="fas fa-spinner fa-spin"></i> Test en cours...</>
              ) : (
                <><i className="fas fa-plug"></i> Tester la Connexion</>
              )}
            </button>

            <button 
              type="submit" 
              disabled={dbSaving}
              className={`px-6 py-2.5 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm ${
                dbSaving ? 'bg-slate-300 text-slate-500 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-300'
              }`}
            >
              {dbSaving ? 'Sauvegarde...' : 'Sauvegarder la Config'}
            </button>
          </div>

          <div className="text-right text-xs">
            {dbStatus === 'success' && <span className="text-emerald-600 font-bold"><i className="fas fa-check"></i> {dbMessage}</span>}
            {dbStatus === 'error' && <span className="text-red-600 font-bold"><i className="fas fa-times"></i> {dbMessage}</span>}
          </div>
        </form>
      </div>

      {/* SECTION WEBHOOK */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 relative overflow-hidden">
        {/* Overlay si DB non connectée */}
        {(!dbConfig.url || (testResult?.success === false && !dbConfig.hasPassword)) && (
          <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-10 flex items-center justify-center">
            <div className="bg-white border border-slate-200 p-4 rounded-lg shadow-lg text-slate-500 font-bold text-sm flex items-center gap-2">
              <i className="fas fa-lock text-slate-400"></i>
              Connectez la Base de Données pour configurer le Webhook
            </div>
          </div>
        )}

        <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100">
          <div className="w-12 h-12 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center text-xl shadow-inner">
            <i className="fas fa-network-wired"></i>
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-800">Configuration Webhook</h2>
            <p className="text-slate-500 text-xs">Synchronisation n8n / ERP (stocké en base)</p>
          </div>
        </div>

        <form onSubmit={handleSaveWebhook} className="space-y-6">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">URL Endpoint</label>
            <div className="relative">
                <i className="fas fa-bolt absolute left-3 top-3.5 text-slate-400"></i>
                <input 
                type="url" 
                required
                className="w-full pl-10 p-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm bg-slate-50"
                value={webhookUrl}
                onChange={e => setWebhookUrl(e.target.value)}
                />
            </div>
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {webhookStatus === 'success' && <span className="text-emerald-600 text-xs font-bold"><i className="fas fa-check-circle"></i> Mis à jour</span>}
              {webhookStatus === 'error' && <span className="text-red-600 text-xs font-bold"><i className="fas fa-times-circle"></i> Erreur lors de l'enregistrement</span>}
            </div>
            <button 
              type="submit" 
              disabled={webhookSaving}
              className={`px-6 py-2.5 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm ${
                webhookSaving ? 'bg-slate-300 text-slate-500' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-200'
              }`}
            >
              {webhookSaving ? '...' : 'Enregistrer'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminSettings;

import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs/promises';
import cors from 'cors';
import PocketBase from 'pocketbase';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_CONFIG_FILE = path.join(__dirname, 'db_config.json');

const app = express();
const PORT = process.env.PORT || 3000;

// Configuration Fallback via Env (pour le premier démarrage)
const ENV_WEBHOOK_URL = process.env.WEBHOOK_URL;

// Instance globale PocketBase
let pb = null;

// Middleware
app.use(cors());
app.use(express.json({ limit: '10mb' }));
app.use(express.static(path.join(__dirname, 'dist')));

// --- GESTION CONFIGURATION POCKETBASE ---

async function getDbConfig() {
  try {
    const data = await fs.readFile(DB_CONFIG_FILE, 'utf8');
    return JSON.parse(data);
  } catch (e) {
    // Si pas de fichier de config local, on utilise les variables d'environnement
    return {
      url: process.env.POCKETBASE_URL,
      email: process.env.POCKETBASE_ADMIN_EMAIL,
      password: process.env.POCKETBASE_ADMIN_PASSWORD
    };
  }
}

async function saveDbConfig(config) {
  await fs.writeFile(DB_CONFIG_FILE, JSON.stringify(config, null, 2));
}

// Initialisation / Reconnexion dynamique
async function initPocketBase() {
  console.log('🔄 Initialisation connexion PocketBase...');
  const config = await getDbConfig();

  if (!config.url) {
    console.warn('⚠️ Aucune URL PocketBase configurée.');
    return false;
  }

  try {
    pb = new PocketBase(config.url);
    pb.autoCancellation(false); // Évite l'annulation des requêtes concurrentes

    if (config.email && config.password) {
      // Support PocketBase v0.23+ : Utilisation de la collection système _superusers
      await pb.collection('_superusers').authWithPassword(config.email, config.password);
      console.log(`✅ Connecté à PocketBase Admin (${config.url})`);
      return true;
    } else {
      console.warn('⚠️ Identifiants Admin manquants.');
      return false;
    }
  } catch (error) {
    console.error('❌ Erreur Connexion PocketBase:', error.originalError || error.message);
    return false;
  }
}

// Lancement initial
initPocketBase();

// --- API SYSTEME ---

// Lire la config actuelle (sans exposer le mot de passe complet si possible, mais ici requis pour l'UI)
app.get('/api/admin/db-config', async (req, res) => {
  const config = await getDbConfig();
  res.json({
    url: config.url || '',
    email: config.email || '',
    hasPassword: !!config.password // On indique juste si un mot de passe est set
  });
});

// Mettre à jour la config et reconnecter
app.post('/api/admin/db-config', async (req, res) => {
  try {
    const { url, email, password } = req.body;

    // On récupère l'ancienne config pour garder le mot de passe si non fourni
    const oldConfig = await getDbConfig();
    const newConfig = {
      url,
      email,
      password: password || oldConfig.password // Garder l'ancien si vide
    };

    await saveDbConfig(newConfig);
    const success = await initPocketBase();

    if (success) {
      res.json({ success: true, message: "Connexion établie et sauvegardée." });
    } else {
      res.status(400).json({ success: false, message: "Impossible de se connecter avec ces identifiants." });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- API METIER ---

/**
 * Middleware pour vérifier si PB est prêt
 */
const requirePb = (req, res, next) => {
  if (!pb || !pb.authStore.isValid) {
    return res.status(503).json({ error: "PocketBase non connecté. Vérifiez la configuration Admin." });
  }
  next();
};

app.get('/api/bootstrap', async (req, res) => {
  try {
    if (!pb) {
      // Mode dégradé si PB non configuré
      return res.json({ webhook_url: "", clients: [], poseurs: [] });
    }

    // Récupération parallèle avec gestion d'erreurs silencieuse
    const [clientsReq, poseursReq, configReq] = await Promise.all([
      pb.collection('clients').getFullList({ sort: 'nom' }).catch(() => []), 
      pb.collection('poseurs').getFullList({ sort: 'nom' }).catch(() => []),
      pb.collection('config').getFirstListItem('').catch(() => ({ webhook_url: "" }))
    ]);

    const finalWebhookUrl = configReq.webhook_url || ENV_WEBHOOK_URL || "http://default-webhook.com";

    res.json({
      webhook_url: finalWebhookUrl,
      clients: clientsReq.map(c => ({ id: c.id, nom: c.nom, codeClient: c.codeClient, typeAffaire: c.typeAffaire })),
      poseurs: poseursReq.map(p => ({ id: p.id, nom: p.nom, entreprise: p.entreprise, telephone: p.telephone, specialite: p.specialite, codeSalarie: p.codeSalarie }))
    });
  } catch (error) {
    console.error('Erreur Bootstrap:', error);
    res.status(500).json({ error: "Erreur serveur" });
  }
});

// --- CRUD ---
app.post('/api/clients', requirePb, async (req, res) => {
  try { res.json(await pb.collection('clients').create(req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/clients/:id', requirePb, async (req, res) => {
  try { res.json(await pb.collection('clients').update(req.params.id, req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/clients/:id', requirePb, async (req, res) => {
  try { await pb.collection('clients').delete(req.params.id); res.json({ success: true }); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/poseurs', requirePb, async (req, res) => {
  try { res.json(await pb.collection('poseurs').create(req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/poseurs/:id', requirePb, async (req, res) => {
  try { res.json(await pb.collection('poseurs').update(req.params.id, req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/poseurs/:id', requirePb, async (req, res) => {
  try { await pb.collection('poseurs').delete(req.params.id); res.json({ success: true }); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/config', requirePb, async (req, res) => {
  try {
    let record;
    try {
      const existing = await pb.collection('config').getFirstListItem('');
      record = await pb.collection('config').update(existing.id, req.body);
    } catch (e) {
      record = await pb.collection('config').create(req.body);
    }
    res.json(record);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Support SPA
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`🚀 Serveur BuildScan AI sur le port ${PORT}`);
});

import React, { useState, useMemo, useEffect } from 'react';
import { ConstructionOrderData, Client, LogEntry } from '../types';
import Terminal from './Terminal';

interface SqlExporterProps {
  data: ConstructionOrderData;
  originalFile?: File;
}

const SqlExporter: React.FC<SqlExporterProps> = ({ data, originalFile }) => {
  const [copied, setCopied] = useState(false);
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [logs, setLogs] = useState<LogEntry[]>([]);

  const DEFAULT_WEBHOOK_URL = "http://194.116.0.110:5678/webhook-test/857f9b11-6d28-4377-a63b-c431ff3fc324";

  const addLog = (type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  };

  const clearLogs = () => setLogs([]);

  useEffect(() => {
    addLog('info', `Système prêt. Module de transmission binaire activé.`);
    addLog('info', `En attente d'envoi vers n8n via Multipart FormData.`);
  }, []);

  const mappedClient = useMemo(() => {
    if (!data.nom_client) return null;
    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return null;
    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = data.nom_client.toLowerCase().trim();
      return clients.find(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });
    } catch (e) {
      return null;
    }
  }, [data.nom_client]);

  const escapeSql = (str: string | null) => str ? str.replace(/'/g, "''").trim() : "";
  const soc = "SAM";
  const ets = "001";
  const secteur = "80";
  const phase = "0";
  const chantier = escapeSql(data.num_bon_travaux).replace(/\D/g, '').substring(0, 6) || "000000";
  const imputation = `${secteur}${chantier}${phase}`;
  const fullAddress = escapeSql(data.adresse_intervention);
  const cpMatch = fullAddress.match(/\d{5}/);
  const codePostal = cpMatch ? cpMatch[0] : "";
  const codeCliFour = mappedClient ? mappedClient.codeClient : "";
  const codeTrv = mappedClient?.typeAffaire || "O3-0";
  const descTravaux = escapeSql(data.descriptif_travaux);

  const sqlInsert = `INSERT INTO \`a_cht\` 
(\`soc\`, \`ets\`, \`secteur\`, \`chantier\`, \`phase\`, \`imputation\`, \`libelle1\`, \`descriptif_tvx\`, \`descriptif_trvx2\`, \`code_postal\`, \`inter_cli\`, \`tel_cli\`, \`code_ouvert\`, \`code_raz_fin_exo\`, \`code_clifour\`, \`code_trv\`) 
VALUES ('${soc}', '${ets}', '${secteur}', '${chantier}', '${phase}', '${imputation}', '${escapeSql(data.nom_client).substring(0, 40)}', '<p>Import BuildScan AI : ${descTravaux.substring(0, 500)}</p>', '${fullAddress.substring(0, 120)}', '${codePostal}', '${escapeSql(data.nom_client).substring(0, 40)}', '${escapeSql(data.coord_gardien).substring(0, 30)}', '4', 'N', '${codeCliFour}', '${codeTrv}');`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(sqlInsert);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const transmitToWebhook = async () => {
    setTransmitting(true);
    setTransmitStatus('idle');
    const webhookUrl = localStorage.getItem('buildscan_webhook_url') || DEFAULT_WEBHOOK_URL;

    // Création du FormData pour un envoi MULTIPART
    // C'est ce qui permet à n8n de voir le PDF comme un fichier binaire réel
    const formData = new FormData();

    if (originalFile) {
      formData.append('file', originalFile, 'document.pdf');
    }

    // --- Données ERP / Calculées ---
    formData.append('codeClient', codeCliFour);
    formData.append('code_trv', codeTrv);
    formData.append('num_chantier', chantier);
    formData.append('imputation', imputation);
    formData.append('source', "BuildScan AI");
    formData.append('timestamp', new Date().toISOString());

    // --- Données Brutes Extraites (Intégralité) ---
    formData.append('num_bon_travaux', data.num_bon_travaux || '');
    formData.append('nom_client', data.nom_client || '');
    formData.append('adresse_intervention', data.adresse_intervention || '');
    formData.append('coord_gardien', data.coord_gardien || '');
    formData.append('delai_intervention', data.delai_intervention || '');
    formData.append('date_intervention', data.date_intervention || '');
    formData.append('descriptif_travaux', data.descriptif_travaux || '');

    // Alias pour compatibilité existante
    formData.append('libelle', data.nom_client || '');

    addLog('request', `Envoi Multipart/FormData vers n8n... (Fichier inclus : ${originalFile ? 'OUI' : 'NON'})`, {
      codeClient: codeCliFour,
      imputation: imputation,
      adresse: data.adresse_intervention,
      fileSize: originalFile ? `${(originalFile.size / 1024).toFixed(2)} KB` : 'N/A'
    });

    try {
      const response = await fetch(webhookUrl, {
        method: 'POST',
        // Note: Ne PAS mettre de Content-Type header, le navigateur le fera automatiquement avec le boundary pour FormData
        body: formData
      });

      if (response.ok) {
        setTransmitStatus('success');
        addLog('response', `Réponse n8n : Succès (HTTP ${response.status})`);
      } else {
        throw new Error(`Erreur n8n : ${response.status}`);
      }
    } catch (err: any) {
      console.error("Erreur Webhook:", err);
      setTransmitStatus('error');
      addLog('error', `Échec transmission: ${err.message}`);
    } finally {
      setTransmitting(false);
      setTimeout(() => setTransmitStatus('idle'), 3000);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800">
        <div className="px-6 py-4 border-b border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-500/20 text-blue-400 rounded flex items-center justify-center">
              <i className="fas fa-network-wired text-sm"></i>
            </div>
            <div>
              <h3 className="text-white font-bold uppercase tracking-wider text-xs">Intégration <span className="text-blue-400">n8n / ERP</span></h3>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-tighter">Transmission Binaire</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={copyToClipboard}
              className={`px-3 py-1.5 rounded-lg font-bold text-[10px] transition-all flex items-center gap-2 ${copied ? 'bg-emerald-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-700'}`}
            >
              {copied ? 'SQL Copié' : 'Copier SQL'}
            </button>

            <button 
              disabled={transmitting || !mappedClient}
              onClick={transmitToWebhook}
              className={`px-4 py-1.5 rounded-lg font-bold text-[10px] transition-all flex items-center gap-2 shadow-lg ${
                transmitStatus === 'success' ? 'bg-green-600 text-white' : 
                transmitStatus === 'error' ? 'bg-red-600 text-white' :
                !mappedClient ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700' :
                'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/40'
              }`}
            >
              {transmitting ? 'Envoi...' : transmitStatus === 'success' ? 'Transmis !' : 'Transmettre à n8n'}
            </button>
          </div>
        </div>

        <div className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            <div className={`p-3 rounded-lg border flex items-center justify-between transition-all ${mappedClient ? 'bg-emerald-900/20 border-emerald-800' : 'bg-amber-900/20 border-amber-800'}`}>
              <div>
                <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Code Client</p>
                <p className={`text-sm font-mono font-bold ${mappedClient ? 'text-emerald-400' : 'text-amber-400'}`}>
                  {codeCliFour || 'MANQUANT'}
                </p>
              </div>
              {mappedClient ? <i className="fas fa-link text-emerald-500"></i> : <i className="fas fa-unlink text-amber-500"></i>}
            </div>
            <div className="p-3 bg-blue-900/20 border border-blue-800 rounded-lg flex items-center justify-between">
              <div>
                <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Affaire</p>
                <p className="text-sm font-mono font-bold text-blue-400">{codeTrv}</p>
              </div>
              <i className="fas fa-folder-open text-blue-500"></i>
            </div>
          </div>

          <div className="relative group">
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">Script SQL de secours</p>
            <div className="max-h-32 overflow-y-auto rounded-lg border border-slate-800 bg-black/40 p-3">
              <pre className="text-emerald-300 text-[10px] font-mono leading-relaxed whitespace-pre-wrap opacity-70 group-hover:opacity-100 transition-opacity">
                {sqlInsert}
              </pre>
            </div>
          </div>
        </div>
      </div>

      <Terminal logs={logs} onClear={clearLogs} />
    </div>
  );
};

export default SqlExporter;

